import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fr/fra.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fr/fra.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fr/fra.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione" tabindex="-1">Introduzione <a class="header-anchor" href="#introduzione" aria-label="Permalink to “Introduzione”">​</a></h1><p>In questo capitolo cercheremo di risolvere il problema classico della misura del cerchio (ciclo = cerchio metròs = misura) ed anche la rettificazione della circonferenza, cioè &quot;stendere&quot; la circonferenza su una retta e trovare la relazione tra tale segmento ed il raggio.</p><p>Il problema della rettificazione della circonferenza, dato il raggio, è uno dei <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> grandi problemi dell&#39;antichità:</p><blockquote><p><strong>Gli altri erano:</strong></p><p>Con riga e compasso trovare:</p><ul><li>La trisezione di un angolo: come dividere un angolo in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> parti uguali.</li><li>La duplicazione del cubo: dato un cubo trovare il lato di un altro cubo che abbia volume doppio del dato.</li></ul></blockquote><p>Il primo problema è risolvibile solo in casi particolari perché equivale a risolvere un&#39;equazione di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn><mtext>-o</mtext></mrow><annotation encoding="application/x-tex">3\\text{-o}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span><span class="mord text"><span class="mord">-o</span></span></span></span></span> grado e quindi non è sempre risolvibile con riga e compasso.</p><p>Anche il secondo non è risolvibile con riga e compasso: l&#39;uso di riga e compasso equivale a risolvere il problema mediante equazioni risolubili con le sole operazioni razionali ed anche radici quadrate: per risolvere il problema invece devo trovare la radice cubica di un numero.</p><p>Anche il terzo problema, che è quello che ci interessa, non è risolvibile con riga e compasso, ma useremo il metodo, già usato per introdurre i numeri reali, delle sezioni di Dedekind, utilizzando però delle classi contigue di misure di perimetri (per la circonferenza) e di aree (per il cerchio).</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};